# Hypothesis: motifs are copies of a shape. In each demo band, some motif instance is "completed"/marked 8.
# Look at the top band (rows 0-4) motifs vs bottom band (rows 10-14). Compare shape occurrences.
# Top band motifs: at columns 6-9?, 11-14?, 16-19? Find bounding boxes of connected components
def comps(g):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]==2 and not seen[r][c]:
                st=[(r,c)]; seen[r][c]=True; cells=[]
                while st:
                    a,b=st.pop(); cells.append((a,b))
                    for dr in(-1,0,1):
                        for dc in(-1,0,1):
                            nr,nc=a+dr,b+dc
                            if 0<=nr<H and 0<=nc<W and g[nr][nc]==2 and not seen[nr][nc]:
