            adj=sum(res[(r+dr)%pitch][(c+dc)%pitch]==2 for dr in(-1,0,1) for dc in(-1,0,1) if (dr,dc)!=(0,0))>0
            marked = max(hz)>=2 or max(vz)>=2 or adj
            O[r,c]=8 if marked else res[r,c]
    return O.tolist()

