    # safer: class value 2 iff ALL its occurrences across ALL bands are 2
    cnt=collections.defaultdict(int)
    tot=collections.defaultdict(int)
    for r in range(H):
        for c in range(W):
            if I[r,c]==2:
                cnt[(r%pitch,c%pitch)]+=1; tot[(r%pitch,c%pitch)]+=1
    cls={(k,v) for k,v in cnt.items() if v==tot[k]}
    def res_val(r,c):
        k=(r%pitch,c%pitch)
        return 2 if ((r,c)==(0,0) and False) else (2 if (k in cls or True) else 0)
    # simpler: 2 iff class has any 2; conflicts resolved later per-cell check
    res=[[2 if any(I[(r+p*dr)][(c+q*p)%W]==2 for dr in range((H-(r%p)+H)%H // pitch) for q in range(1)) else 0
          for c in range(W)] for r in range(H)]
    # fallback simple version matching earlier working variant
    ok=set()
    for k in cls: ok.add(k)
    for r in range(H):
        for c in range(W):
            if (r%pitch,c%pitch) in cls: res[r][c]=2
            elif all(I[(r+dr*p)%H][(c+dc*p)%W]!=2 for dr,dc in [(0,0)]) : pass
    O=[row[:] for row in I.tolist()]
    for r in range(0,H,pitch):
        for c in range(0,W,pitch):
            hz=runs_seq([res[r][(c+dc)%pitch] for dc in range(pitch)])
            vz=runs_seq([res[(rr)%pitch][c] for rr in range(H)])
            adj=sum(res[(r+dr)%pitch][(c+dc)%pitch]==2 for dr in(-1,0,1) for dc in(-1,0,1) if (dr,dc)!=(0,0))>0
            marked = max(hz)>=2 or max(vz)>=2 or adj
            O[r][c]=8 if marked else res[r][c]
    return O

