def solve_line_rule(tab,pitch,H,W,O=None,verbose=False):
    # tiled pattern
    T=np.zeros((pitch,pitch),int)
    def get(r,c):
        return tab.get((r%pitch,c%pitch),set())
    # check consistent single values first
    okc=True
    for r in range(pitch):
        for c in range(pitch):
            s=get(r,c)
            if len(s)>1: okc=False
    L=pitch
    def h_run(r,c):
        # walk row r cyclically starting at c; find run containing c
        best=-1; cur=0
        for k in range(2*L):
            cc=(c+k)%L
            v=T[r,cc]
            if v==2: cur+=1
            else:
                if cur>=2: best=max(best,cur)
                cur=0
            if k==L-1 and cur>=2: best=max(best,cur)
        return best
    def v_run(r,c):
        cur=0; best=-1
        for k in range(2*L):
            rr=(r+k)%L
            v=T[rr,c]
            if v==2: cur+=1
            else:
                if cur>=2: best=max(best,cur)
                cur=0
            if k==L-1 and cur>=2: best=max(best,cur)
        return best
    predm=[]
    for r in range(H):
        for c in range(W):
            if r%pitch!=0 or c%pitch!=0: continue
            pr=h_run(r%pitch,c%pitch); pv=v_run(r%pitch,c%pitch)
            if O is not None: exp=int(O[r,c]==8)
            if O is None: pred=int(pr>=2 and pv>=2)
            elif pr>=2 and pv>=2 == exp: pred=exp
            else: predm.append((r,c,pitch,pr,pv,exp))
    return predm,pred

