def f(I):
    I=np.array(I); H,W=I.shape
    # horizontal band height: number of rows before first zero row
    br=bh=None
    z=[r for r in range(H) if all(v==0 for v in I[r])]
    bh=z[0] if z else H
    band=I[:bh,:]
    bw=band.shape[1]
    # horizontal pitch pw: smallest p with band columns repeating exactly at period p within each 5-row? Actually check band[:,c]==band[:,c%p] false due to full-grid period. Instead find pw from pattern of single band copy: columns periodic mod pw across whole band width
    cands=[]
    for p in range(1,bw+1):
        if all(np.array_equal(band[:,c],band[:,c%p]) for c in range(bw) if c>=p): cands.append(p)
    pw=cands[0] if cands else 1
    # vertical period vp: smallest vp such that band rows repeat: band[r]==band[r%vp]? but band may be truncated by a zero separator. First find vp among divisors... check band[r]==band[(r+? ) ]. Try vp candidates where bottom rows equal top rows cyclically over band length: band[r%vp] equality holds only if vp divides bh or band is partial. Use: vp = min p such that band[p:]==band[0:bh-p]
    vc=[]
    for p in range(1,bh):
        if np.array_equal(band[p:],band[:bh-p]): vc.append(p)
    vp=vc[0] if vc else 1
    # build table over (row mod vp, col mod pw) from ALL cells in band that are 2; also include markers from other bands if present (nonzero non-2 colors? inputs have only 0/2 in bands)
    tab=collections.defaultdict(set)
