    pp,ppc=vp,pw
    def hrun(rr,cc):
        cur=0
        for k in range(2*ppc):
            cc=(cc+k)%ppc
            if tab.get((rr,cc))=={2}: cur+=1
            else: break
        return cur
    def vrun(rr,cc):
